package com.sonora.music;

import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity {
 private final int BG=0xff070b1c, PANEL=0xff0d1630, PANEL2=0xff132143, CYAN=0xff19e6dc, PURPLE=0xff963cff, WHITE=0xfff1f5ff, MUTED=0xff9aafd2;
 private LinearLayout root, body, tracksPanel; private TextView nowTitle, nowSub, play; private EditText search; private MusicService service; private boolean bound=false; private ArrayList<Uri> uris=new ArrayList<>(); private ArrayList<String> names=new ArrayList<>(); private HashSet<String> favorites=new HashSet<>(); private ArrayList<String> playlist=new ArrayList<>(); private String page="Inicio"; private Handler handler=new Handler();
 private final int PICK=45;
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=((MusicService.LocalBinder)b).getService();bound=true; syncQueue(); render();}public void onServiceDisconnected(ComponentName n){bound=false;service=null;}};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(0); load(); if(Build.VERSION.SDK_INT>=26) startForegroundService(new Intent(this,MusicService.class)); else startService(new Intent(this,MusicService.class)); bindService(new Intent(this,MusicService.class),connection,BIND_AUTO_CREATE); render(); handler.post(tick);}
 private Runnable tick= new Runnable(){public void run(){if(bound&&service!=null){if(nowTitle!=null&&service.getIndex()>=0&&service.getIndex()<names.size()){nowTitle.setText(names.get(service.getIndex()));play.setText(service.isPlaying()?"Ⅱ":"▶");}}handler.postDelayed(this,700);}};
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} GradientDrawable bg(int c,int stroke,int r){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{c, c==PANEL?PANEL2:c});d.setCornerRadius(dp(r));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;} void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 void load(){android.content.SharedPreferences p=getSharedPreferences("sonora",0);favorites=new HashSet<>(p.getStringSet("favorites",new HashSet<>()));playlist=new ArrayList<>(p.getStringSet("playlist",new HashSet<>()));try{org.json.JSONArray a=new org.json.JSONArray(p.getString("library","[]"));for(int i=0;i<a.length();i++){Uri u=Uri.parse(a.getJSONObject(i).getString("uri"));String n=a.getJSONObject(i).getString("name");uris.add(u);names.add(n);}}catch(Exception ignored){}}
 void saveLibrary(){try{org.json.JSONArray a=new org.json.JSONArray();for(int i=0;i<uris.size();i++){org.json.JSONObject o=new org.json.JSONObject();o.put("uri",uris.get(i).toString());o.put("name",names.get(i));a.put(o);}getSharedPreferences("sonora",0).edit().putString("library",a.toString()).apply();}catch(Exception ignored){}}
 void save(){android.content.SharedPreferences.Editor e=getSharedPreferences("sonora",0).edit();e.putStringSet("favorites",new HashSet<>(favorites));e.putStringSet("playlist",new HashSet<>(playlist));e.apply();}
 void syncQueue(){if(service!=null)service.setQueue(uris,names);}
 void render(){root=col();root.setBackgroundColor(BG);pad(root,16,12,16,12);setContentView(root);
  LinearLayout header=row();TextView logo=txt("〰  S O N O R A",22,CYAN,true);header.addView(logo,new LinearLayout.LayoutParams(0,dp(42),1));TextView eq=txt("♫  ⋮",23,WHITE,true);eq.setOnClickListener(v->showMore());header.addView(eq);root.addView(header);
  TextView tagline=txt("TU MÚSICA, EN TODAS PARTES",10,MUTED,true);tagline.setLetterSpacing(.14f);root.addView(tagline);
  LinearLayout nav=row();nav.setPadding(0,dp(14),0,dp(12));for(String p:new String[]{"Inicio","Biblioteca","Favoritos","Listas","Ecualizador"}){TextView b=txt(p,11,page.equals(p)?CYAN: MUTED,true);pad(b,7,10,7,10);b.setBackground(bg(page.equals(p)?PANEL2:BG,page.equals(p)?CYAN:0,18));b.setOnClickListener(v->{page=p;render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(38),1);lp.setMargins(2,0,2,0);nav.addView(b,lp);}root.addView(nav);
  if(page.equals("Inicio")){LinearLayout hero=col();hero.setBackground(bg(PANEL,PURPLE,20));pad(hero,18,18,18,18);TextView h=txt("Tu sonido.\nTu universo.",26,WHITE,true);hero.addView(h);TextView sub=txt("Reproduce tu música local con una experiencia neón.",13,MUTED,false);pad(sub,0,8,0,14);hero.addView(sub);Button add=button("＋  Añadir canciones",CYAN,BG);add.setOnClickListener(v->pick());hero.addView(add);root.addView(hero);TextView section=txt("RECIÉN ESCUCHADO · BIBLIOTECA",13,WHITE,true);pad(section,0,18,0,8);root.addView(section);}
  if(page.equals("Biblioteca")||page.equals("Inicio")){search=new EditText(this);search.setSingleLine(true);search.setTextColor(WHITE);search.setHintTextColor(MUTED);search.setHint("⌕  Buscar canciones o artistas...");search.setBackground(bg(PANEL2,CYAN,18));pad(search,14,0,14,0);root.addView(search,new LinearLayout.LayoutParams(-1,dp(46)));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){fillTracks(s.toString());}public void afterTextChanged(android.text.Editable e){}});}
  if(page.equals("Favoritos"))root.addView(txt("TUS CANCIONES FAVORITAS",13,CYAN,true)); if(page.equals("Listas")){root.addView(txt("LISTAS DE REPRODUCCIÓN",13,CYAN,true));Button create=button("＋ Crear lista desde selección",PURPLE,WHITE);create.setOnClickListener(v->{if(service!=null&&service.getIndex()>=0&&service.getIndex()<names.size()){playlist.add(names.get(service.getIndex()));save();Toast.makeText(this,"Añadida a tu lista",Toast.LENGTH_SHORT).show();render();}});root.addView(create);}
  if(page.equals("Ecualizador")){equalizerUI();}
  tracksPanel=col();LinearLayout.LayoutParams listLp=new LinearLayout.LayoutParams(-1,0,1);listLp.topMargin=dp(8);root.addView(tracksPanel,listLp);fillTracks("");
  LinearLayout mini= row();mini.setBackground(bg(PANEL2,PURPLE,18));pad(mini,12,10,12,10);LinearLayout info=col();nowTitle=txt("SONORA está lista",13,WHITE,true);nowSub=txt("Elige una canción de tu biblioteca",10,MUTED,false);info.addView(nowTitle);info.addView(nowSub);mini.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView prev=txt("|◀",18,WHITE,true);prev.setOnClickListener(v->{if(service!=null)service.previous();});mini.addView(prev);play=txt(bound&&service!=null&&service.isPlaying()?"Ⅱ":"▶",24,CYAN,true);pad(play,14,4,14,4);play.setOnClickListener(v->{if(service!=null)service.toggle();});mini.addView(play);TextView next=txt("▶|",18,WHITE,true);next.setOnClickListener(v->{if(service!=null)service.next();});mini.addView(next);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,-2);mp.topMargin=dp(10);root.addView(mini,mp);
 }
 Button button(String s,int c,int tc){Button b=new Button(this);b.setText(s);b.setTextColor(tc);b.setAllCaps(false);b.setBackground(bg(c,0,18));return b;}
 void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("audio/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req!=PICK||res!=RESULT_OK||data==null)return;ArrayList<Uri> picked=new ArrayList<>();if(data.getClipData()!=null){for(int x=0;x<data.getClipData().getItemCount();x++)picked.add(data.getClipData().getItemAt(x).getUri());}else if(data.getData()!=null)picked.add(data.getData());for(Uri u:picked){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}if(!uris.contains(u)){uris.add(u);names.add(titleOf(u));}}saveLibrary();syncQueue();page="Biblioteca";render();}
 String titleOf(Uri u){String name="Pista local";try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int k=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(k>=0)name=c.getString(k);}}catch(Exception ignored){}return name;}
 void fillTracks(String query){if(tracksPanel==null)return;tracksPanel.removeAllViews();ArrayList<Integer> shown=new ArrayList<>();for(int i=0;i<names.size();i++){String n=names.get(i);boolean ok=n.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT));if(page.equals("Favoritos"))ok&=favorites.contains(n);if(page.equals("Listas"))ok&=playlist.contains(n);if(ok)shown.add(i);}if(shown.isEmpty()){TextView empty=txt(uris.isEmpty()?"Tu biblioteca está vacía.\nAñade archivos MP3, M4A, WAV o FLAC desde tu teléfono.":"No hay canciones en esta sección.",13,MUTED,false);pad(empty,12,20,12,20);tracksPanel.addView(empty);if(uris.isEmpty()){Button add=button("Seleccionar música",PURPLE,WHITE);add.setOnClickListener(v->pick());tracksPanel.addView(add);}return;}for(int idx:shown){final int n=idx;LinearLayout item=row();item.setBackground(bg(PANEL,0,14));pad(item,10,9,10,9);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,-2);ip.setMargins(0,0,0,dp(6));tracksPanel.addView(item,ip);TextView art=txt("♫",22,n%2==0?CYAN:PURPLE,true);art.setGravity(Gravity.CENTER);art.setBackground(bg(PANEL2,0,10));item.addView(art,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout info=col();pad(info,10,0,4,0);info.addView(txt(names.get(idx),13,WHITE,true));info.addView(txt("ARCHIVO LOCAL · AUDIO",10,MUTED,false));item.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView fav=txt(favorites.contains(names.get(idx))?"♥":"♡",22,favorites.contains(names.get(idx))?PURPLE:MUTED,true);fav.setOnClickListener(v->{if(!favorites.add(names.get(n)))favorites.remove(names.get(n));save();fillTracks(search==null?"":search.getText().toString());});item.addView(fav);TextView more=txt("⋮",23,WHITE,true);more.setPadding(dp(12),0,dp(3),0);more.setOnClickListener(v->trackMenu(n));item.addView(more);item.setOnClickListener(v->{if(service!=null){service.setQueue(uris,names);service.playIndex(n);nowTitle.setText(names.get(n));}});}}
 void trackMenu(int i){String[] opts={"Reproducir ahora","Agregar a favoritos","Agregar a lista","Eliminar de biblioteca"};new AlertDialog.Builder(this).setTitle(names.get(i)).setItems(opts,(d,w)->{if(w==0&&service!=null){service.setQueue(uris,names);service.playIndex(i);}if(w==1){if(!favorites.add(names.get(i)))favorites.remove(names.get(i));save();render();}if(w==2){playlist.add(names.get(i));save();Toast.makeText(this,"Añadida a la lista",Toast.LENGTH_SHORT).show();}if(w==3){uris.remove(i);names.remove(i);saveLibrary();syncQueue();render();}}).show();}
 void equalizerUI(){LinearLayout box=col();box.setBackground(bg(PANEL,PURPLE,18));pad(box,14,14,14,14);TextView title=txt("ECUALIZADOR GRÁFICO",16,WHITE,true);box.addView(title);TextView hint=txt("Los controles dependen del ecualizador compatible del dispositivo.",11,MUTED,false);pad(hint,0,4,0,8);box.addView(hint);Switch enabled=new Switch(this);enabled.setText("Activar efectos de audio");enabled.setTextColor(WHITE);enabled.setChecked(false);enabled.setOnCheckedChangeListener((v,on)->{if(service!=null){service.enableEqualizer(on);if(on)populateBands(box);}});box.addView(enabled);root.addView(box);}
 void populateBands(LinearLayout box){if(service==null)return;for(int b=0;b<service.bandCount();b++){final int band=b;TextView label=txt((service.centerFreq(b)/1000f)+" kHz",11,MUTED,true);box.addView(label);SeekBar bar=new SeekBar(this);bar.setMax(Math.max(1,service.equalizerMax()-service.equalizerMin()));bar.setProgress(service.equalizerLevels()[b]-service.equalizerMin());bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){if(u)service.setBand(band,(short)(p+service.equalizerMin()));}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});box.addView(bar);}}
 void showMore(){String[] options={"Añadir canciones","Biblioteca","Favoritos","Listas","Ecualizador","Aleatorio","Repetir canción"};new AlertDialog.Builder(this).setTitle("SONORA · Controles").setItems(options,(d,w)->{if(w==0)pick();else if(w<=4){page=new String[]{"","Biblioteca","Favoritos","Listas","Ecualizador"}[w];render();}else if(service!=null){if(w==5)service.setShuffle(!service.getShuffle());else service.setRepeat(!service.getRepeat());Toast.makeText(this,"Ajuste actualizado",Toast.LENGTH_SHORT).show();}}).show();}
 @Override protected void onDestroy(){handler.removeCallbacks(tick);if(bound)unbindService(connection);super.onDestroy();}
}
